// Counts occurrences of each item type. Callers say how to read the type off
// their own element, so both insured items (`type`) and claimed damages
// (`itemType`) can be tallied without projecting one shape onto the other.
const countsByType = <T>(elements: T[], itemTypeOf: (element: T) => string): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const element of elements) {
    const itemType = itemTypeOf(element);
    counts.set(itemType, (counts.get(itemType) ?? 0) + 1);
  }
  return counts;
};

const itemTypeOfItem = (item: Item): string => item.type;
const itemTypeOfDamage = (damage: Damage): string => damage.itemType;

